def reachingPoints(sx, sy, tx, ty):
    # Loop backwards from (tx, ty) to (sx, sy)
    while tx > sx and ty > sy:
        if tx > ty:
            tx %= ty
        else:
            ty %= tx
    # Handle cases where one coordinate matches
    if tx == sx and ty == sy:
        return True
    if tx == sx and ty > sy and (ty - sy) % sx == 0:
        return True
    if ty == sy and tx > sx and (tx - sx) % sy == 0:
        return True
    return False
